import Product from '../models/Product.js';

// @desc    Get all products (Public)
// @route   GET /api/products
export const getProducts = async (req, res, next) => {
  try {
    const products = await Product.find({}).sort({ createdAt: -1 });
    res.json(products);
  } catch (error) {
    next(error);
  }
};

// @desc    Get single product by ID
// @route   GET /api/products/:id
export const getProductById = async (req, res, next) => {
  try {
    const product = await Product.findById(req.params.id);
    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }
    res.json(product);
  } catch (error) {
    next(error);
  }
};

// @desc    Create a new product (Admin)
// @route   POST /api/products
export const createProduct = async (req, res, next) => {
  try {
    const { name, description, price, category, stockQuantity, imageUrl, isFeatured } = req.body;

    if (!name || !description || price === undefined || stockQuantity === undefined) {
      return res.status(400).json({ message: 'Please fill in all required product fields' });
    }

    const product = await Product.create({
      name,
      description,
      price,
      category,
      stockQuantity,
      imageUrl,
      isFeatured
    });

    res.status(201).json(product);
  } catch (error) {
    next(error);
  }
};

// @desc    Update product & stock levels (Admin)
// @route   PUT /api/products/:id
export const updateProduct = async (req, res, next) => {
  try {
    const product = await Product.findById(req.params.id);

    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    Object.assign(product, req.body);
    const updatedProduct = await product.save();

    res.json(updatedProduct);
  } catch (error) {
    next(error);
  }
};

// @desc    Delete a product (Admin)
// @route   DELETE /api/products/:id
export const deleteProduct = async (req, res, next) => {
  try {
    const product = await Product.findById(req.params.id);

    if (!product) {
      return res.status(404).json({ message: 'Product not found' });
    }

    await product.deleteOne();
    res.json({ message: 'Product deleted successfully' });
  } catch (error) {
    next(error);
  }
};